/* IAM Atlas — ampliação curricular versionada, 2026-10-16.
 * Índices originais 0–15 são preservados para não invalidar o progresso local.
 * Fontes e licenças devem ser revisadas periodicamente. */
const EXPANSION_VERSION = '2026.10.16';
const NEW_MODULES = [];
function addModule(area, title, description, reference, tools, access, rows) {
  const index = DATA.modules.length;
  DATA.modules.push([area, title, description, ...rows.map(r => r[0])]);
  const guideSet = rows.map(r => {
    const [name, concept, action, acceptance, specificUrl] = r;
    const steps = action.split(' | ');
    const url = specificUrl || reference;
    const importance = description + ' A análise deve explicitar o risco de concessão indevida, perda de rastreabilidade ou indisponibilidade.';
    const practice = steps.map((t, i) => (i + 1) + '. ' + t).join('\n');
    const verify = 'Entrega verificável: ' + acceptance + ' Explique a decisão técnica, o menor privilégio e uma possibilidade de falha.';
    practicalGuides[name] = {
      importance, when: tools + '. Requisitos: ' + access,
      steps: steps.concat(['Capture evidências sem expor usuários reais, senhas, tokens ou dados pessoais.','Documente como reverter as mudanças após a verificação.']),
      source: url
    };
    return {concept, importance, when: tools, practice, verify, tools, url};
  });
  topicGuides.push(guideSet);
  NEW_MODULES.push(index);
}
